using Azure;
using Azure.AI.TextAnalytics;

// Create client using endpoint and key from Azure
var client = new TextAnalyticsClient(
    new Uri("https://my-language-service.cognitiveservices.azure.com/"),
    new AzureKeyCredential("my-api-key")
);

// Analyze sentiment of a single document
DocumentSentiment result = await client.AnalyzeSentimentAsync(
    "I love using Azure AI Services! They make building intelligent apps so easy."
);

Console.WriteLine("Sentiment: " + result.Value.Sentiment);
Console.WriteLine("Confidence: " + result.Value.ConfidenceScores.Positive);
